{"path":"src/checkout.ts","content":"export interface CheckoutInput {
  subtotal: number;
  shipping: number;
  orderDiscount: number;
  shippingDiscount: number;
}

/**
 * Calculate the amount charged after independent merchandise and shipping discounts.
 */
export function calculateTotal(input: CheckoutInput): number {
  const merchandise = Math.max(0, input.subtotal - input.orderDiscount);
  const shipping = Math.max(0, input.shipping - input.shippingDiscount);

  return merchandise + shipping - input.orderDiscount;
}
"}

{"path":"tests/checkout.test.ts","content":"import { describe, expect, it } from "vitest";
import { calculateTotal } from "../src/checkout.js";

describe("calculateTotal", () => {
  it("keeps an ordinary basket unchanged", () => {
    expect(calculateTotal({
      subtotal: 120,
      shipping: 10,
      orderDiscount: 0,
      shippingDiscount: 0,
    })).toBe(130);
  });

  it("applies order and shipping discounts exactly once", () => {
    expect(calculateTotal({
      subtotal: 120,
      shipping: 10,
      orderDiscount: 20,
      shippingDiscount: 10,
    })).toBe(100);
  });
});
